package org.apache.commons.math.analysis.solvers;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.ConvergenceException;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.analysis.FunctionEvaluationException;
import org.apache.commons.math.analysis.UnivariateRealFunction;
import org.apache.commons.math.exception.ConvergenceException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Unit tests for UnivariateRealSolverUtils.bracket
 */
public class UnivariateRealSolverUtils_bracket_TriageGen2Test {

    @Test
    public void testFunctionIsNull() {
        try {
            UnivariateRealSolverUtils.bracket(null, 0, -10, 10, 10);
            fail("Expected IllegalArgumentException due to null function");
        } catch (IllegalArgumentException e) {
            assertEquals("function is null", e.getMessage());
        } catch (Exception e) {
            fail("Expected IllegalArgumentException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testMaximumIterationsNonPositive() {
        UnivariateRealFunction f = x -> x * x - 4;
        try {
            UnivariateRealSolverUtils.bracket(f, 0, -10, 10, 0);
            fail("Expected IllegalArgumentException due to non-positive iterations");
        } catch (IllegalArgumentException e) {
            // Note: The exact message depends on MathRuntimeException formatting, 
            // checking if it contains the important part.
            assert(e.getMessage().contains("bad value for maximum iterations number"));
        } catch (Exception e) {
            fail("Expected IllegalArgumentException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testInvalidParameters() {
        UnivariateRealFunction f = x -> x * x - 4;

        // initial < lowerBound
        try {
            UnivariateRealSolverUtils.bracket(f, -5, 0, 10, 10);
            fail("Expected IllegalArgumentException: initial < lowerBound");
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("invalid bracketing parameters"));
        }

        // initial > upperBound
        try {
            UnivariateRealSolverUtils.bracket(f, 15, 0, 10, 10);
            fail("Expected IllegalArgumentException: initial > upperBound");
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("invalid bracketing parameters"));
        }

        // lowerBound >= upperBound
        try {
            UnivariateRealSolverUtils.bracket(f, 5, 10, 5, 10);
            fail("Expected IllegalArgumentException: lowerBound >= upperBound");
        } catch (IllegalArgumentException e) {
            assert(e.getMessage().contains("invalid bracketing parameters"));
        }
    }

    @Test
    public void testSuccessfulBracketing() throws Exception {
        // Function f(x) = x^2 - 4. Roots at -2 and 2.
        // Initial at 0. Bracket should find a range containing a root.
        UnivariateRealFunction f = x -> x * x - 4;
        double[] result = UnivariateRealSolverUtils.bracket(f, 0, -5, 5, 10);

        // Result [a, b] should have f(a)*f(b) < 0
        assertEquals(false, f.value(result[0]) * f.value(result[1]) > 0);
    }

    @Test
    public void testConvergenceExceptionDueToMaxIterations() {
        // Function that never crosses zero in the range
        UnivariateRealFunction f = x -> x * x + 1; 
        try {
            UnivariateRealSolverUtils.bracket(f, 0, -5, 5, 5);
            fail("Expected ConvergenceException due to max iterations");
        } catch (ConvergenceException e) {
            // Success
        } catch (Exception e) {
            fail("Expected ConvergenceException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testConvergenceExceptionDueToNoSignChange() {
        // Function that stays positive throughout the range
        UnivariateRealFunction f = x -> 10.0; 
        try {
            UnivariateRealSolverUtils.bracket(f, 0, -5, 5, 100);
            fail("Expected ConvergenceException due to no sign change");
        } catch (ConvergenceException e) {
            // Success
        } catch (Exception e) {
            fail("Expected ConvergenceException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testFunctionEvaluationException() {
        // Function that throws exception when evaluated at a specific point
        UnivariateRealFunction f = x -> {
            if (x == 1.0) {
                throw new FunctionEvaluationException(new RuntimeException("Eval error"), 1.0);
            }
            return x;
        };

        try {
            // Force evaluation at 1.0
            // Since increments are 1.0, starting at 0 and searching might hit 1.0
            UnivariateRealSolverUtils.bracket(f, 0.5, -5, 5, 10);
            fail("Expected FunctionEvaluationException");
        } catch (FunctionEvaluationException e) {
            // Success
        } catch (Exception e) {
            fail("Expected FunctionEvaluationException, but caught: " + e.getClass().getName());
        }
    }

    @Test
    public void testBracketAtBoundaries() throws Exception {
        // Function where root is exactly at a boundary
        // f(x) = x. Root at 0.
        UnivariateRealFunction f = x -> x;

        // Start at 0, lower bound -5, upper bound 5.
        // a will become -1, b will become 1.
        // f(-1) = -1, f(1) = 1. fa*fb = -1 < 0.
        double[] result = UnivariateRealSolverUtils.bracket(f, 0, -5, 5, 10);
        assertEquals(-1.0, result[0], 1e-9);
        assertEquals(1.0, result[1], 1e-9);
    }

    @Test
    public void testLoopTerminationViaBounds() throws Exception {
        // Function that has sign change, but we test the (a > lowerBound || b < upperBound) condition
        // If the function is f(x) = x and we are already at the bounds.
        UnivariateRealFunction f = x -> x;
        // If initial is 0, lower is -1, upper is 1.
        // Iteration 1: a = max(-1, -1) = -1, b = min(1, 1) = 1.
        // f(-1)=-1, f(1)=1. Loop terminates because fa*fb < 0.
        double[] result = UnivariateRealSolverUtils.bracket(f, 0, -1, 1, 10);
        assertEquals(-1.0, result[0], 1e-9);
        assertEquals(1.0, result[1], 1e-9);
    }
}
